// FoundationStereo's `stem_2` against its own modules in FP64. Fixtures generated by
// tests/fixtures/stem/generate.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use teeny_core::name_scope::name_scope;
use vision_rs::models::stereo::stem::stem_2;

/// Random weights on a 30x46 image (to 15x23).
#[test]
#[serial]
fn stem_2_matches_pytorch() -> anyhow::Result<()> {
    check_block(
        "stem/small",
        "stem/small",
        &[("image", &[1, 3, 30, 46])],
        |i| {
            let _g = name_scope("stem_2");
            vec![("", stem_2::<f32>(&i[0]))]
        },
        1e-4,
    )?;
    Ok(())
}

/// A real FoundationStereo checkpoint's `stem_2` on the sample left image at 224x320
/// (to 112x160). Fixtures from tests/fixtures/stem/generate.py with `--run` and
/// `--out` (`stem_real/` under `FS_REAL_FIXTURES`); run with `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn stem_2_matches_real_checkpoint() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dir = format!("{root}/stem_real");
    check_block(
        "stem_real",
        &dir,
        &[("image", &[1, 3, 224, 320])],
        |i| {
            let _g = name_scope("stem_2");
            vec![("", stem_2::<f32>(&i[0]))]
        },
        1e-4,
    )?;
    Ok(())
}
